// Reference Model Solution (C++ - DP Coin Change)
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, target;
    if (cin >> n >> target) {
        vector<int> coins(n);
        for (int i = 0; i < n; i++) cin >> coins[i];

        vector<int> dp(target + 1, target + 2);
        dp[0] = 0;
        for (int coin : coins) {
            for (int i = coin; i <= target; i++) {
                dp[i] = min(dp[i], dp[i - coin] + 1);
            }
        }
        cout << (dp[target] > target ? -1 : dp[target]) << endl;
    }
    return 0;
}

